/**
 * Avery Institute preview service — protected server-side PDF rasterization.
 * Private originals are never returned. This function emits only heavily watermarked JPEG pages.
 */
import "jsr:@supabase/functions-js/edge-runtime.d.ts"
import { createClient } from "npm:@supabase/supabase-js@2"
import {
  CompositeOperator,
  ImageMagick,
  type IMagickImage,
  initializeImageMagick,
  MagickFormat,
  MagickReadSettings,
} from "npm:@imagemagick/magick-wasm@0.0.40"

const wasmBytes = await Deno.readFile(
  new URL("magick.wasm", import.meta.resolve("npm:@imagemagick/magick-wasm@0.0.40")),
)
await initializeImageMagick(wasmBytes)

const encoder = new TextEncoder()
const MAX_PREVIEW_PAGES = 12
const MAX_JPEG_BYTES = 4_500_000
const MAX_PREVIEW_WIDTH = 960
const APP_ORIGINS = new Set([
  "https://averyinsti-qnbmu2v8.manus.space",
  "http://localhost:3000",
])

function corsHeaders(origin: string | null): HeadersInit {
  return {
    "Access-Control-Allow-Origin": origin && APP_ORIGINS.has(origin)
      ? origin
      : "https://averyinsti-qnbmu2v8.manus.space",
    "Access-Control-Allow-Headers": "authorization, apikey, content-type",
    "Access-Control-Allow-Methods": "POST, OPTIONS",
    "Vary": "Origin",
  }
}

function respond(body: Record<string, unknown>, status: number, origin: string | null) {
  return Response.json(body, { status, headers: corsHeaders(origin) })
}

function watermarkJpeg(preview: IMagickImage, pageNumber: number): Uint8Array {
  const outputWidth = Math.min(MAX_PREVIEW_WIDTH, preview.width)
  const outputHeight = Math.max(1, Math.round(preview.height * (outputWidth / preview.width)))
  preview.resize(outputWidth, outputHeight)

  const svg = `
      <svg xmlns="http://www.w3.org/2000/svg" width="${outputWidth}" height="${outputHeight}" viewBox="0 0 ${outputWidth} ${outputHeight}">
        <rect width="100%" height="100%" fill="#ffffff" opacity="0.18"/>
        <g transform="rotate(-28 ${outputWidth / 2} ${outputHeight / 2})" fill="#5d1908" opacity="0.72" font-family="Arial, Helvetica, sans-serif" font-size="${Math.max(24, Math.round(outputWidth / 17))}" font-weight="700" letter-spacing="1.3">
          <text x="-${outputWidth}" y="-${outputHeight * 0.25}">AVERY INSTITUTE • PREVIEW ONLY • NOT FOR DISTRIBUTION</text>
          <text x="-${outputWidth}" y="-${outputHeight * 0.02}">AVERY INSTITUTE • PREVIEW ONLY • NOT FOR DISTRIBUTION</text>
          <text x="-${outputWidth}" y="${outputHeight * 0.21}">AVERY INSTITUTE • PREVIEW ONLY • NOT FOR DISTRIBUTION</text>
          <text x="-${outputWidth}" y="${outputHeight * 0.44}">AVERY INSTITUTE • PREVIEW ONLY • NOT FOR DISTRIBUTION</text>
          <text x="-${outputWidth}" y="${outputHeight * 0.67}">AVERY INSTITUTE • PREVIEW ONLY • NOT FOR DISTRIBUTION</text>
          <text x="-${outputWidth}" y="${outputHeight * 0.90}">AVERY INSTITUTE • PREVIEW ONLY • NOT FOR DISTRIBUTION</text>
          <text x="-${outputWidth}" y="${outputHeight * 1.13}">AVERY INSTITUTE • PREVIEW ONLY • NOT FOR DISTRIBUTION</text>
        </g>
        <rect x="12" y="12" width="${outputWidth - 24}" height="${outputHeight - 24}" fill="none" stroke="#5d1908" stroke-width="5" opacity="0.72"/>
        <text x="24" y="${outputHeight - 28}" fill="#5d1908" opacity="0.92" font-family="Arial, Helvetica, sans-serif" font-size="16" font-weight="700">CUSTOMER PREVIEW • PAGE ${pageNumber} • DOWNLOAD REQUIRES PURCHASE</text>
      </svg>`

  return ImageMagick.read(encoder.encode(svg), (overlay) => {
    preview.composite(overlay, CompositeOperator.Over)
    preview.strip()
    preview.quality = 58
    return preview.write(MagickFormat.Jpeg, (data) => data)
  })
}

Deno.serve(async (req) => {
  const origin = req.headers.get("origin")
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders(origin) })
  if (req.method !== "POST") return respond({ error: "Method not allowed." }, 405, origin)
  if (origin && !APP_ORIGINS.has(origin)) return respond({ error: "Origin not allowed." }, 403, origin)

  const authorization = req.headers.get("authorization")
  if (!authorization?.startsWith("Bearer ")) return respond({ error: "Authentication is required." }, 401, origin)

  const supabaseUrl = Deno.env.get("SUPABASE_URL")
  const anonKey = Deno.env.get("SUPABASE_ANON_KEY")
  const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")
  if (!supabaseUrl || !anonKey || !serviceRoleKey) {
    return respond({ error: "Preview service is not configured." }, 500, origin)
  }

  let resourceId = ""
  try {
    const payload = await req.json()
    resourceId = typeof payload?.resourceId === "string" ? payload.resourceId : ""
  } catch {
    return respond({ error: "A JSON request body is required." }, 400, origin)
  }
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(resourceId)) {
    return respond({ error: "A valid resource ID is required." }, 400, origin)
  }

  const userClient = createClient(supabaseUrl, anonKey, {
    global: { headers: { Authorization: authorization } },
    auth: { autoRefreshToken: false, persistSession: false },
  })
  const { data: userResult, error: userError } = await userClient.auth.getUser()
  if (userError || !userResult.user) return respond({ error: "Unable to verify the signed-in user." }, 401, origin)

  const adminClient = createClient(supabaseUrl, serviceRoleKey, {
    auth: { autoRefreshToken: false, persistSession: false },
  })
  const { data: profile, error: profileError } = await adminClient
    .from("profiles")
    .select("role")
    .eq("id", userResult.user.id)
    .maybeSingle()
  if (profileError || profile?.role !== "admin") {
    return respond({ error: "Administrator access is required to generate previews." }, 403, origin)
  }

  const { data: resource, error: resourceError } = await adminClient
    .from("resources")
    .select("id, storage_path, mime_type, page_count")
    .eq("id", resourceId)
    .maybeSingle()
  if (resourceError || !resource?.storage_path) return respond({ error: "Resource file not found." }, 404, origin)
  if (resource.mime_type !== "application/pdf" && !resource.storage_path.toLowerCase().endsWith(".pdf")) {
    return respond({ error: "Previews can only be generated for PDF resources." }, 400, origin)
  }

  const { data: originalPdf, error: downloadError } = await adminClient.storage
    .from("resource-files")
    .download(resource.storage_path)
  if (downloadError || !originalPdf) return respond({ error: "Unable to read the private PDF." }, 502, origin)

  const pageNumbers = Array.from(
    { length: Math.max(1, Math.min(Number(resource.page_count) || 1, MAX_PREVIEW_PAGES)) },
    (_, index) => index + 1,
  )
  let renderedPages: Uint8Array[]
  try {
    const pdfSettings = new MagickReadSettings({
      frameIndex: 0,
      frameCount: pageNumbers.length,
      width: MAX_PREVIEW_WIDTH,
    })
    pdfSettings.format = MagickFormat.Pdf
    renderedPages = ImageMagick.readCollection(
      new Uint8Array(await originalPdf.arrayBuffer()),
      pdfSettings,
      (pdfPages) => Array.from(pdfPages).map((page, index) => watermarkJpeg(page, pageNumbers[index] ?? index + 1)),
    )
  } catch (error) {
    console.error("PDF rasterization failed", error)
    return respond({ error: "Unable to rasterize this PDF for preview." }, 422, origin)
  }
  if (!renderedPages.length) return respond({ error: "This PDF does not contain previewable pages." }, 422, origin)

  const uploadedPaths: string[] = []
  try {
    for (const [index, jpeg] of renderedPages.entries()) {
      const pageNumber = pageNumbers[index] ?? index + 1
      if (!jpeg.byteLength || jpeg.byteLength > MAX_JPEG_BYTES) {
        throw new Error(`Preview page ${pageNumber} does not meet the safe-size limit.`)
      }
      const path = `${resource.id}-full-preview-page-${pageNumber}.jpg`
      const { error: uploadError } = await adminClient.storage
        .from("resource-thumbnails")
        .upload(path, jpeg, {
          cacheControl: "31536000",
          contentType: "image/jpeg",
          upsert: true,
        })
      if (uploadError) throw uploadError
      uploadedPaths.push(path)
    }

    const thumbnailPath = `${resource.id}-full-preview-page-1.jpg`
    const { error: updateError } = await adminClient
      .from("resources")
      .update({ thumbnail_path: thumbnailPath })
      .eq("id", resource.id)
    if (updateError) throw updateError

    return respond({ thumbnailPath, pages: uploadedPaths.length }, 200, origin)
  } catch (error) {
    console.error("Preview upload failed", error)
    if (uploadedPaths.length) await adminClient.storage.from("resource-thumbnails").remove(uploadedPaths)
    return respond({ error: "Unable to store the watermarked customer preview." }, 500, origin)
  }
})
